import JSON
using SpecialFunctions

"""
	gen( x, filepath )

Generate fixture data and write to file.

# Arguments

* `x`: domain
* `filepath::AbstractString`: filepath of the output file

# Examples

``` julia
julia> x = range( Float32( 0.5 ), stop = Float32( 1.5 ), length = 3000 );
julia> gen( x, \"./data.json\" );
```
"""
function gen( x, filepath )
	y = Array{Float32}( undef, length(x) );
	for i in eachindex(x)
		y[i] = Float32( SpecialFunctions.erfcinv( Float64( x[i] ) ) );
	end

	data = Dict([
		("x", x),
		("expected", y)
	]);

	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# 0.5 <= x <= 1.5 (linear regime)
x = range( Float32( 0.5 ), stop = Float32( 1.5 ), length = 3000 );
out = joinpath( dir, "x_0.5_1.5.json" );
gen( x, out );

# 0.25 <= 2-x <= 0.5
x = range( Float32( 1.5 ), stop = Float32( 1.75 ), length = 500 );
out = joinpath( dir, "x_1.5_1.75.json" );
gen( x, out );

# 0.25 <= x <= 0.5
x = range( Float32( 0.25 ), stop = Float32( 0.5 ), length = 500 );
out = joinpath( dir, "x_0.25_0.5.json" );
gen( x, out );

# 0.0002 <= 2-x <= 0.25
x = range( Float32( 1.75 ), stop = Float32( 1.9998 ), length = 500 );
out = joinpath( dir, "x_1.75_1.9998.json" );
gen( x, out );

# 0.0002 <= x <= 0.25
x = range( Float32( 0.0002 ), stop = Float32( 0.25 ), length = 500 );
out = joinpath( dir, "x_0.0002_0.25.json" );
gen( x, out );

# 1.1920929e-7 <= 2-x <= 0.0002 (stop is the largest single-precision floating-point number less than 2)
x = range( Float32( 1.9998 ), stop = Float32( 1.9999999 ), length = 500 );
out = joinpath( dir, "x_1.9998_2.json" );
gen( x, out );

# 1e-16 <= x <= 0.0002 (log-spaced)
x = Float32.( exp10.( range( -16, stop = log10( 0.0002 ), length = 500 ) ) );
out = joinpath( dir, "x_1e-16_0.0002.json" );
gen( x, out );

# 1e-44 <= x <= 1e-16 (log-spaced; extends into subnormal single-precision floating-point numbers)
x = Float32.( exp10.( range( -44, stop = -16, length = 500 ) ) );
out = joinpath( dir, "x_1e-44_1e-16.json" );
gen( x, out );
